// ChatHub — routes incoming WebSocket messages to Message Service
public class ChatHub : Hub
{
    private readonly IConnectionMapping _connections;
    private readonly IEventBus _eventBus;
    private readonly IIdempotencyStore _idempotency;

    public ChatHub(IConnectionMapping connections, IEventBus eventBus, IIdempotencyStore idempotency)
    {
        _connections = connections;
        _eventBus = eventBus;
        _idempotency = idempotency;
    }

    // Client sends: { clientMsgId, conversationId, text, timestamp }
    public async Task SendMessage(OutgoingMessage message)
    {
        // Idempotency guard: same clientMsgId within 24h = duplicate, ignore
        if (await _idempotency.ExistsAsync(message.ClientMsgId, TimeSpan.FromHours(24)))
            return;
        await _idempotency.RecordAsync(message.ClientMsgId, TimeSpan.FromHours(24));

        var serverMsgId = Guid.NewGuid();
        var serverTimestamp = DateTime.UtcNow;

        var msg = new ChatMessage
        {
            MessageId = serverMsgId,
            ConversationId = message.ConversationId,
            SenderId = Context.UserIdentifier,
            Text = message.Text,
            ClientMsgId = message.ClientMsgId,
            SentAt = serverTimestamp,
            Status = MessageStatus.Sent
        };

        // Persist + broadcast atomically via outbox pattern
        await _eventBus.Publish(new MessagePersisted(msg));

        // Ack to sender only — fan-out happens via consumer group
        await Clients.Caller.SendAsync("MessageAck", new { serverMsgId = serverMsgId, serverTimestamp = serverTimestamp });
    }

    public override async Task OnDisconnectedAsync(Exception? exception)
    {
        var userId = Context.UserIdentifier;
        _connections.Remove(userId, Context.ConnectionId);

        if (!_connections.IsUserOnline(userId))
        {
            await _eventBus.Publish(new UserWentOffline(userId, DateTime.UtcNow));
        }
        await base.OnDisconnectedAsync(exception);
    }
}

// Presence heartbeat endpoint — called by client every 15s
app.MapPost("/api/presence/heartbeat", async (HttpContext ctx, RedisDb redis) =>
{
    var userId = ctx.User.FindFirst(ClaimTypes.NameIdentifier)!.Value;
    var key = string.Format("presence:user:{0}", userId);
    await redis.KeyExpireAsync(key, TimeSpan.FromSeconds(30));
    await redis.KeyPersistAsync(key); // reset TTL
    return Results.Ok();
});
